materialize.profile.json:
{
  "schema": "loop.profile.v1",
  "project": "toy",
  "target": "maximize the toy score without regressions",
  "metric": "score",
  "modes": ["eval"],
  "paths": {"loop": ".toy/loop", "coverage": "docs/knowledge/coverage.json"},
  "boundaries": ["deterministic", "no-lookahead"],
  "fronts": {
    "debug": {"required": true, "sub_axes": ["correctness", "conservation"]},
    "improve": {"required": true, "sub_axes": ["entry"]}
  },
  "pipeline": [
    {"id": "evaluate", "kind": "evaluate", "command": "toy eval", "artifact": "toy.json"}
  ],
  "gates": {"objective": "score delta > 0", "invariants": "toy test"},
  "completion": {"rule": "coverage", "require_coverage": true, "require_delivery": true}
}
